<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowLeft,Layers3,MapPin,Navigation,Search,Ticket,X,ChevronUp,Map} from 'lucide-vue-next'
import {api} from '../api'
import type {Network} from '../types'
import {fallbackNetwork,guidePerformances,performanceCountdown,refreshPerformance,scenicNames,type GuidePerformance} from '../data/guide'
import {demoRoute} from '../demoRouting'
import {journey,focusedDraftDay,loadJourney,localDate,clock,addChoice,choice,nameOf} from '../journey'
import GuideMap from '../components/GuideMap.vue'
import CityMap from '../components/CityMap.vue'
const route=useRoute(),router=useRouter(),scenicId=ref(String(route.query.scenic||'wansui'))
const demo=computed(()=>route.query.demo==='1')
const cityMode=computed(()=>!demo.value)
const mapView=computed(()=>String(route.query.scenic||'city'))
const scenicName=computed(()=>scenicNames[scenicId.value]||scenicNames.wansui)
const network=ref<Network>(fallbackNetwork(scenicId.value)),routeNetwork=ref<Network>(),loading=ref(false),error=ref(''),searchOpen=ref(false),search=ref(''),layerOpen=ref(false),performanceLayer=ref(true),selectedNode=ref(''),currentNode=ref('gate'),now=ref(Date.now()),sheetOpen=ref(false),filter=ref('all')
const performances=ref<GuidePerformance[]>([]),selectedEvent=ref<GuidePerformance>(),summary=ref<{distance:number;minutes:number;arrival:string}>(),message=ref('')
let loadVersion=0,ticker:ReturnType<typeof setInterval>|undefined
const nodes=computed(()=>network.value.features.filter(x=>x.geometry.type==='Point'))
const place=computed(()=>nodes.value.find(p=>p.properties.id===selectedNode.value))
const listed=computed(()=>performances.value.filter(p=>(p.name+p.venue).includes(search.value.trim())&&(filter.value==='all'||p.status===filter.value)).sort((a,b)=>+new Date(a.startsAt)-+new Date(b.startsAt)))
const task=computed(()=>focusedDraftDay.value?.stops.find(s=>s.progress==='pending'))
const date=computed(()=>focusedDraftDay.value?.business_date||localDate())
async function loadScene(id:string){const version=++loadVersion;scenicId.value=id;loading.value=true;routeNetwork.value=undefined;selectedEvent.value=undefined;selectedNode.value='';summary.value=undefined;message.value='';error.value='';performances.value=[]
 try{const [n,s]=await Promise.allSettled([api.network(id),api.schedules(id,date.value)]);if(version!==loadVersion)return;network.value=n.status==='fulfilled'?n.value:fallbackNetwork(id)
 if(demo.value)performances.value=guidePerformances(id)
 else if(s.status==='fulfilled')performances.value=s.value.items.filter(x=>x.kind==='show'&&!x.is_simulated&&x.node_id&&x.ends_at&&new Date(x.starts_at).toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'})===date.value).map(x=>refreshPerformance({id:x.id,scenicId:id,nodeId:x.node_id!,name:x.name,venue:String(nodes.value.find(n=>n.properties.id===x.node_id)?.properties.name||'地点待核实'),startsAt:x.starts_at,endsAt:x.ends_at,sourceType:'reported',sourceLabel:'来源：已接入场次资料 · 地图点位仍为示意',isSimulated:false,status:'upcoming'}))
 else error.value='场次资料暂时无法加载，可重试。'
 }finally{if(version===loadVersion)loading.value=false}}
async function switchScene(id:string){await router.replace({path:'/guide',query:{scenic:id,...(demo.value?{demo:'1'}:{})}})}
function selectEvent(event:GuidePerformance){selectedEvent.value=event;selectedNode.value=event.nodeId;sheetOpen.value=true}
function navigate(id:string){const result=demoRoute(network.value,currentNode.value,id);if(!result){message.value='示意路网不连通，无法生成路线';routeNetwork.value=undefined;summary.value=undefined;return}selectedNode.value=id;routeNetwork.value=result.network;summary.value={distance:result.distance,minutes:result.minutes,arrival:clock(new Date(Date.now()+result.minutes*60000).toISOString())};message.value='演示路线，非实际导航';sheetOpen.value=false}
function toggleDemo(){void router.replace({path:'/guide',query:{scenic:scenicId.value,...(!demo.value?{demo:'1'}:{})}})}
function clear(){selectedNode.value='';selectedEvent.value=undefined;message.value=''}
function setCurrent(){currentNode.value=selectedNode.value||'gate';message.value='当前位置设为选中的示意点；不代表 GPS 定位。'}
function addEvent(){if(!selectedEvent.value)return;const fact=journey.catalog.find(x=>x.record.kind==='show_session'&&x.record.fact_id===selectedEvent.value!.id&&x.ready&&!x.record.is_demo);if(!fact){message.value='这场演出尚未匹配可加入城市行程的有效记录，请先核对公告。';return}addChoice(choice('show',fact.record.fact_id,selectedEvent.value.name))}
watch(()=>route.query.scenic,v=>{if(v&&!cityMode.value)void loadScene(String(v))})
watch(()=>cityMode.value,v=>{if(!v)void loadScene(String(route.query.scenic||'wansui'))})
onMounted(()=>{void loadJourney();if(!cityMode.value)void loadScene(scenicId.value);ticker=setInterval(()=>{now.value=Date.now();performances.value=performances.value.map(refreshPerformance);if(selectedEvent.value)selectedEvent.value=performances.value.find(p=>p.id===selectedEvent.value?.id)},1000)})
onBeforeUnmount(()=>{loadVersion++;if(ticker)clearInterval(ticker)})
</script>
<template><div class="guide-page task-map-page"><header class="guide-header"><div class="guide-header-main"><RouterLink to="/" class="guide-back" aria-label="返回景区探索"><ArrowLeft :size="17"/></RouterLink><div class="guide-brand"><div><strong>汴梁地图</strong><small>{{cityMode?(mapView==='city'?'从这里，走向下一站':scenicNames[mapView]||'景区视角'):scenicName}}</small></div></div><div class="guide-header-actions"><button v-if="!cityMode" type="button" aria-label="搜索导览内容" @click="searchOpen=!searchOpen"><Search :size="18"/></button><button v-if="!cityMode" type="button" aria-label="切换地图图层" @click="layerOpen=!layerOpen"><Layers3 :size="18"/></button></div></div><div class="map-mode-tabs" role="tablist" aria-label="地图范围"><RouterLink to="/guide?mode=city" :class="{active:cityMode&&mapView==='city'}">开封全市</RouterLink><button type="button" role="tab" :aria-selected="mapView==='wansui'" :class="{active:mapView==='wansui'}" @click="switchScene('wansui')">万岁山大宋武侠城</button><button type="button" role="tab" :aria-selected="mapView==='qingming'" :class="{active:mapView==='qingming'}" @click="switchScene('qingming')">清明上河园</button></div></header>
 <main class="guide-main"><template v-if="cityMode"><CityMap :view="mapView" :place-id="typeof route.query.place==='string'?route.query.place:undefined"/><RouterLink class="demo-switch quiet-link" :to="'/guide?demo=1&scenic='+(mapView==='city'?'wansui':mapView)">查看景区示意交互演示</RouterLink></template><template v-else><div v-if="task" class="map-journey-context"><MapPin :size="16"/><span>行程下一站：{{nameOf(task.place_id)}}</span><RouterLink :to="'/city-trip/'+journey.trip!.id">返回行程</RouterLink></div><div v-if="demo" class="demo-mode-notice">交互演示模式 · 下列场次为模拟日程，不是官方演出时间</div><div v-if="searchOpen" class="guide-search"><Search :size="15"/><input v-model="search" aria-label="搜索演出或地点" placeholder="搜索演出名称"><button @click="search=''">清除</button></div><section class="guide-map-section"><div v-if="layerOpen" class="guide-layer-popover"><strong>地图图层</strong><label><input type="checkbox" v-model="performanceLayer">演出点位</label><small>当前底图位置为示意，未启用实时客流图层。</small></div><div v-if="loading" class="guide-loading"><span class="spinner"/>正在展开景区示意图…</div><GuideMap v-else :network="network" :route="routeNetwork" :performances="performances" :crowds="[]" :crowd-layer="false" :performance-layer="performanceLayer" :selected-node="selectedNode" :selected-performance="selectedEvent?.id" :current-node="currentNode" @select-node="selectedNode=$event;selectedEvent=undefined" @select-performance="selectEvent" @set-current="setCurrent"/><p class="guide-map-status">示意地图 · 未经地理配准，仅作地点关系和交互展示</p></section>
 <section v-if="place||selectedEvent||message" class="guide-selection-card"><button type="button" class="guide-selection-close" aria-label="关闭信息卡" @click="clear"><X :size="17"/></button><span class="tiny-caption">{{selectedEvent?(demo?'模拟演出':'演出资料'):'示意点位'}}</span><h2>{{selectedEvent?.name||place?.properties.name||'位置提示'}}</h2><p v-if="selectedEvent">{{selectedEvent.venue}} · {{performanceCountdown(selectedEvent,now)}}</p><p v-if="message" role="status">{{message}}</p><small v-if="selectedEvent">{{selectedEvent.sourceLabel}}</small><div class="guide-selection-actions"><button v-if="place" class="button primary" type="button" @click="navigate(String(place.properties.id))"><Navigation :size="15"/>查看示意路线</button><button v-if="selectedEvent&&!demo" class="button secondary" type="button" @click="addEvent">加入素材篮</button></div></section>
 <section v-if="summary" class="guide-route-summary"><div><span>演示路线</span><strong>{{summary.minutes}} 分钟 · {{summary.distance}} 米</strong><small>示意距离，非实际导航</small></div><div><span>演示预计到达</span><strong>{{summary.arrival}}</strong><small>不能据此承诺赶上演出</small></div><button type="button" @click="summary=undefined;routeNetwork=undefined">清除路线</button></section>
 <section class="guide-performance-sheet" :class="{expanded:sheetOpen}"><button type="button" class="guide-sheet-handle" :aria-expanded="sheetOpen" aria-label="展开或收起今日演出" @click="sheetOpen=!sheetOpen"><span/><ChevronUp :size="17"/></button><div class="guide-sheet-heading"><div><span class="tiny-caption">{{date}} · {{demo?'模拟日程':'以景区公告为准'}}</span><h1>今日演出</h1></div><div class="guide-sheet-tools"><button v-for="(label,key) in {all:'全部',live:'正在演出',upcoming:'即将开始'}" :key="key" type="button" :class="{active:filter===key}" @click="filter=key">{{label}}</button></div></div><p v-if="error" class="error-state" role="alert">{{error}}<button @click="loadScene(scenicId)">重试</button></p><div v-if="!listed.length&&!loading" class="journey-empty"><Ticket :size="28"/><p>{{demo?'没有符合条件的演出':'暂无当天可核验的完整场次'}}</p><small>没有确定的时间和地点，不会补成真实节目单。</small></div><div v-else class="guide-event-list"><button v-for="event in listed" :key="event.id" type="button" :class="['guide-event-card','status-'+event.status]" @click="selectEvent(event)"><div class="guide-event-time"><strong>{{clock(event.startsAt)}}</strong><small>{{demo?'演示':'已接入资料'}}</small></div><div class="guide-event-body"><h2>{{event.name}}</h2><p><MapPin :size="13"/>{{event.venue}}</p><span class="guide-countdown">{{performanceCountdown(event,now)}}</span></div></button></div></section><button type="button" class="demo-switch quiet-link" :aria-pressed="demo" @click="toggleDemo">{{demo?'退出交互演示':'查看模拟场次与路线交互演示'}}</button></template></main></div></template>
